widget.starter:
def simplify_path(path):
    # Returns the path unchanged. Simplify it with a stack.
    return path

widget.solution:
def simplify_path(path):
    stack = []
    for part in path.split('/'):
        if part == '..':
            if stack:
                stack.pop()
        elif part and part != '.':
            stack.append(part)
    return '/' + '/'.join(stack)

