widget.solution:
def life_step(board):
    rows, cols = len(board), len(board[0])

    def live_neighbours(r, c):
        n = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if (dr or dc) and 0 <= r + dr < rows and 0 <= c + dc < cols:
                    n += board[r + dr][c + dc]
        return n

    out = []
    for r in range(rows):
        row = []
        for c in range(cols):
            n = live_neighbours(r, c)
            row.append(1 if n == 3 or (board[r][c] and n == 2) else 0)
        out.append(row)
    return out

