def longest_valid_parentheses(s):
    # Counts '()' pairs. Find the longest valid run instead.
    return s.count('()') * 2

widget.solution:
def longest_valid_parentheses(s):
    stack = [-1]
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best
